def _table(rows: list[list[str]], title: str | None = None, span: int | None = None) -> str:
    parts = ['<table border="1" cellspacing="0"><tbody>']
    if title:
        n = span or (len(rows[0]) if rows else 1)
        parts.append(
            f'<tr><td colspan="{n}"><p style="text-align:center;"><strong>{title}</strong></p></td></tr>'
        )
    for row in rows:
        cells = "".join(f"<td><p>{cell}</p></td>" for cell in row)
        parts.append(f"<tr>{cells}</tr>")
    parts.append("</tbody></table>")
    return "".join(parts)


